class Solution{public int myAtoi(String s){int i=0,sign=1,r=0;while(i<s.length()&&s.charAt(i)==' ')i++;if(i<s.length()&&(s.charAt(i)=='+'||s.charAt(i)=='-')){if(s.charAt(i++)=='-')sign=-1;}while(i<s.length()&&Character.isDigit(s.charAt(i))){int d=s.charAt(i++)-'0';if(sign>0){if(r>Integer.MAX_VALUE/10||(r==Integer.MAX_VALUE/10&&d>7))return Integer.MAX_VALUE;r=r*10+d;}else{if(r<Integer.MIN_VALUE/10||(r==Integer.MIN_VALUE/10&&d>8))return Integer.MIN_VALUE;r=r*10-d;}}return r;}}
